package com.whale.pet;

import android.app.*;
import android.content.*;
import android.graphics.ImageDecoder;
import android.graphics.drawable.*;
import android.os.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Dependency-free instrumentation tests of the actual Java implementation. */
public final class NativeTests extends Instrumentation {
    private int passed,failed;private final StringBuilder output=new StringBuilder();private PetCatalog catalog;
    private interface Check {void run()throws Exception;}
    private void test(String name,Check check){try{check.run();passed++;output.append("PASS ").append(name).append('\n');}catch(Throwable e){failed++;output.append("FAIL ").append(name).append(": ").append(e).append('\n');}Bundle b=new Bundle();b.putString("stream",output.substring(Math.max(0,output.lastIndexOf("\n",Math.max(0,output.length()-2))+1)));sendStatus(0,b);}
    private void ok(boolean value){if(!value)throw new AssertionError("Expected true");}
    private void eq(double expected,double actual){if(Math.abs(expected-actual)>.00001)throw new AssertionError(expected+" != "+actual);}
    private final class Fixture {
        final long[] time={1000000};final SharedPreferences prefs=getContext().getSharedPreferences(UUID.randomUUID().toString(),0);final PetStore store=new PetStore(prefs,()->time[0]);
        Fixture(){store.read();}
        void seed(String key,Object value)throws Exception{JSONObject s=store.read();s.put(key,value);prefs.edit().putString(PetStore.KEY,s.toString()).commit();}
        void advance(long ms){time[0]+=ms;}
    }
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){
        catalog=new PetCatalog(getTargetContext());PetCatalog.Action food=catalog.category("feed").get(0),play=catalog.category("play").get(0);
        test("Original action counts",()->{eq(106,catalog.clips.size());eq(21,catalog.category("feed").size());eq(24,catalog.category("play").size());eq(45,catalog.ambient.size());});
        test("Every non-transaction animation is discoverable exactly once",()->{Set<String> shown=new HashSet<>();for(PetCatalog.Action a:catalog.spontaneous("all")){ok(!a.transaction());ok(shown.add(a.id));}eq(61,shown.size());for(PetCatalog.Action a:catalog.actions.values())ok(shown.contains(a.id)!=a.transaction());eq(56,catalog.spontaneous("walking").size());eq(8,catalog.spontaneous("resting").size());});
        test("Random pools exclude food, play, drag and inappropriate sleep actions",()->{for(String id:catalog.ambient)ok(!catalog.actions.get(id).transaction()&&!Arrays.asList("rest","action_045","action_060","action_085","action_100","action_097").contains(id));for(String id:catalog.rest)ok(!catalog.actions.get(id).transaction()&&!catalog.walks.contains(id));ok(catalog.restClicks.contains("action_060"));ok(!catalog.ambient.contains("action_060"));});
        test("Rest touch and automatic animation use their own pools",()->{Fixture f=new Fixture();f.store.setMode("resting");final String[] last={null};runOnMainSync(()->{PetEngine engine=new PetEngine(f.store,catalog,new PetEngine.Host(){public void show(String id,Runnable ready){last[0]=id;ready.run();}public void active(boolean value){}public void message(String text){}public void changed(){}public boolean move(boolean right,int duration){throw new AssertionError("Rest must not walk");}public void stopMotion(){}});engine.resume();engine.touch();ok(catalog.restClicks.contains(last[0]));for(int i=0;i<20;i++){engine.drop();engine.autonomous();ok(catalog.rest.contains(last[0]));}engine.pause();});});
        test("Run weighting is 60 percent; all other eligible clips are equal",()->{Random random=new Random(192);Map<String,Integer> counts=new HashMap<>();for(int i=0;i<50000;i++){String id=PetEngine.sampleSpontaneous(catalog,false,true,random);counts.put(id,counts.getOrDefault(id,0)+1);}ok(Math.abs(counts.get("run")/50000d-.60)<.015);eq(48,counts.size());for(Map.Entry<String,Integer> entry:counts.entrySet())if(!entry.getKey().equals("run"))ok(entry.getValue()>280&&entry.getValue()<570);for(int i=0;i<300;i++){ok(!catalog.walks.contains(PetEngine.sampleSpontaneous(catalog,false,false,random)));ok(catalog.rest.contains(PetEngine.sampleSpontaneous(catalog,true,true,random)));}});
        test("Facing metadata matches left/right movement",()->{for(String id:new String[]{"run","action_094"}){ok(PetAnimationView.needsMirror(catalog.clips.get(id),true));ok(!PetAnimationView.needsMirror(catalog.clips.get(id),false));}ok(!PetAnimationView.needsMirror(catalog.clips.get("walk"),true));ok(!PetAnimationView.needsMirror(catalog.clips.get("walk"),false));});
        test("Speech rate, shared clock and no immediate repetition",()->{Fixture f=new Fixture();PetSpeech speech=new PetSpeech(f.store,()->f.time[0],new Random(2));String first=speech.poll();ok(first!=null);ok(speech.poll()==null);ok(new PetSpeech(f.store,()->f.time[0],new Random(3)).poll()==null);f.advance(80000);String second=speech.poll();ok(second!=null&&!first.equals(second));ok(speech.event("touch")!=null);ok(speech.event("touch")==null);f.advance(12000);ok(speech.event("touch")!=null);});
        test("Hunger and fatigue reminders both get a turn",()->{Fixture f=new Fixture();f.seed("energy",8);f.seed("satiety",10);PetSpeech speech=new PetSpeech(f.store,()->f.time[0],new Random(9));String tired=speech.poll();ok(tired!=null);f.advance(80000);String hungry=speech.poll();ok(hungry!=null&&!tired.equals(hungry));f.seed("energy",80);f.seed("satiety",100);String feed=speech.event("feed");ok(feed!=null&&!feed.equals(hungry));ok(speech.poll()==null);});
        test("Repeated mode selection does not spam history",()->{Fixture f=new Fixture();ok(!f.store.setMode("walking"));eq(0,f.store.read().getJSONArray("events").length());ok(f.store.setMode("resting"));ok(!f.store.setMode("resting"));eq(1,f.store.read().getJSONArray("events").length());});
        test("Journal totals use actual effects and merge only close repeated actions",()->{long now=System.currentTimeMillis();JSONArray events=new JSONArray();events.put(new JSONObject().put("kind","feed").put("actionId",food.id).put("name",food.name).put("at",now-60000).put("appliedEffects",new JSONObject().put("satiety",1).put("mood",2)));events.put(new JSONObject().put("kind","feed").put("actionId",food.id).put("name",food.name).put("at",now-10000).put("appliedEffects",new JSONObject().put("satiety",3).put("mood",2)));events.put(new JSONObject().put("kind","mode").put("mode","walking").put("at",now));PetJournal.Summary summary=PetJournal.today(events,now);eq(2,summary.feed);eq(4,summary.satiety);eq(4,summary.mood);eq(2,summary.favoriteCount);eq(1,PetJournal.entries(events,false).size());eq(2,PetJournal.entries(events,false).get(0).count);eq(2,PetJournal.entries(events,true).size());});
        test("All original WebP decode with Android native decoder",()->{for(PetCatalog.Clip clip:catalog.clips.values()){Drawable d=ImageDecoder.decodeDrawable(ImageDecoder.createSource(getTargetContext().getAssets(),clip.file));ok(d instanceof AnimatedImageDrawable);((AnimatedImageDrawable)d).stop();}});
        test("All native crop bounds are within source",()->{for(PetCatalog.Clip c:catalog.clips.values())ok(c.crop.left>=0&&c.crop.top>=0&&c.crop.right<=480&&c.crop.bottom<=270&&c.crop.width()>0&&c.crop.height()>0);});
        test("Props do not change character scale or source anchor",()->{PetCatalog.Clip idle=catalog.clips.get("idle"),bubbles=catalog.clips.get("play_bubbles");eq(idle.bodyScale,bubbles.bodyScale);eq(idle.anchorX,bubbles.anchorX);eq(idle.anchorY,bubbles.anchorY);ok(PetAnimationView.envelope(bubbles,168).width()>PetAnimationView.envelope(idle,168).width());for(PetCatalog.Clip c:catalog.clips.values()){ok(c.bodyScale>0&&c.bodyScale<2);ok(c.anchorX>=0&&c.anchorX<=480&&c.anchorY>=0&&c.anchorY<=270);}});
        test("Confirmation preview shows clamped effects",()->{Fixture f=new Fixture();f.seed("satiety",99);PetCatalog.Action a=catalog.category("feed").get(0);ok(Ui.actualEffects(a,f.store.read()).contains("饱食 +1"));});
        test("Touch shuffle avoids repeats",()->{PetCatalog.Bag bag=new PetCatalog.Bag(catalog.clicks);String last=null;for(int r=0;r<10;r++){Set<String> seen=new HashSet<>();for(int i=0;i<catalog.clicks.size();i++){String next=bag.next();if(i==0)ok(!next.equals(last));ok(seen.add(next));last=next;}}});
        test("Legacy state, events and settings migrate",()->{Fixture f=new Fixture();f.seed("satiety",61);f.seed("energy",22);f.prefs.edit().putString("name","小海").putFloat("x",.32f).commit();PetStore restored=new PetStore(f.prefs,()->f.time[0]);eq(61,restored.read().optDouble("satiety"));eq(22,restored.read().optDouble("energy"));ok(restored.name().equals("小海"));eq(.32,f.prefs.getFloat("x",0));});
        test("Old immersive mode becomes daily",()->{Fixture f=new Fixture();f.seed("mode","immersive");ok(PetStore.mode(f.store.read()).equals("walking"));});
        test("Full hunger blocks all 21 foods",()->{Fixture f=new Fixture();f.seed("satiety",100);for(PetCatalog.Action a:catalog.category("feed")){ok(f.store.refusal(a)!=null);ok(!f.store.action(a,UUID.randomUUID().toString()));}eq(0,f.store.read().getJSONArray("events").length());});
        test("Full remains exactly 100 for 14 minutes",()->{Fixture f=new Fixture();f.seed("satiety",100);f.advance(14*60000);eq(100,f.store.read().optDouble("satiety"));});
        test("At 99 every food is accepted",()->{for(PetCatalog.Action a:catalog.category("feed")){Fixture f=new Fixture();f.seed("satiety",99);ok(f.store.action(a,UUID.randomUUID().toString()));eq(100,f.store.read().optDouble("satiety"));}});
        test("Hunger carries across frequent commits",()->{Fixture f=new Fixture();for(int i=0;i<15;i++){f.advance(60000);f.store.touch();}eq(74,f.store.read().optDouble("satiety"));});
        test("Daily does not recover energy",()->{Fixture f=new Fixture();f.advance(3600000);eq(80,f.store.read().optDouble("energy"));});
        test("Rest restores 30/hour, remains selected",()->{Fixture f=new Fixture();f.seed("energy",8);f.store.setMode("resting");f.advance(3600000);eq(38,f.store.read().optDouble("energy"));ok(PetStore.mode(f.store.read()).equals("resting"));});
        test("Walks consume at most 6/hour",()->{Fixture f=new Fixture();f.store.walk();for(int i=0;i<120;i++){f.advance(30000);f.store.walk();}eq(74,f.store.read().optDouble("energy"));});
        test("Play refusal preserves original actual energy cost",()->{Fixture f=new Fixture();f.seed("energy",9);ok(f.store.refusal(play)!=null);f.seed("energy",80);double before=f.store.read().optDouble("energy");ok(f.store.action(play,"p"));eq(before+play.effects.optDouble("energy"),f.store.read().optDouble("energy"));});
        test("Touch cooldown and mood",()->{Fixture f=new Fixture();ok(f.store.touch());ok(!f.store.touch());eq(71,f.store.read().optDouble("mood"));f.advance(1500);ok(f.store.touch());});
        test("Duplicate confirmation across instances settles once",()->{Fixture f=new Fixture();ok(f.store.action(play,"same"));PetStore second=new PetStore(f.prefs,()->f.time[0]);ok(!second.action(play,"same"));eq(1,f.store.read().getJSONArray("events").length());});
        test("Concurrent confirmation is serialized",()->{Fixture f=new Fixture();ExecutorService pool=Executors.newFixedThreadPool(2);try{Future<Boolean> a=pool.submit(()->f.store.action(play,"race")),b=pool.submit(()->new PetStore(f.prefs,()->f.time[0]).action(play,"race"));ok(a.get(3,TimeUnit.SECONDS)!=b.get(3,TimeUnit.SECONDS));eq(1,f.store.read().getJSONArray("events").length());}finally{pool.shutdownNow();}});
        test("History capped at 100",()->{Fixture f=new Fixture();for(int i=0;i<120;i++)f.store.setMode(i%2==0?"resting":"walking");eq(100,f.store.read().getJSONArray("events").length());});
        test("Engine requires confirmation and keeps already settled effects",()->{Fixture f=new Fixture();runOnMainSync(()->{PetEngine engine=new PetEngine(f.store,catalog,new PetEngine.Host(){public void show(String id,Runnable r){r.run();}public void active(boolean value){}public void message(String text){}public void changed(){}public boolean move(boolean r,int duration){return false;}public void stopMotion(){}});engine.resume();ok(!engine.choose(food,false,"before"));ok(engine.choose(food,true,"after"));engine.pause();eq(1,f.store.read().optJSONArray("events").length());});});
        test("Tap response remains interruptible after cooldown",()->{Fixture f=new Fixture();runOnMainSync(()->{PetEngine engine=new PetEngine(f.store,catalog,new PetEngine.Host(){public void show(String id,Runnable r){r.run();}public void active(boolean v){}public void message(String s){}public void changed(){}public boolean move(boolean r,int d){return false;}public void stopMotion(){}});engine.resume();engine.touch();ok(!engine.manual);f.advance(1600);engine.touch();eq(2,f.store.read().optLong("revision"));engine.pause();});});
        test("Offline rest advances without rendering",()->{Fixture f=new Fixture();f.seed("energy",1);f.store.setMode("resting");f.advance(8*3600000L);eq(100,f.store.read().optDouble("energy"));eq(43,f.store.read().optDouble("satiety"));});
        Bundle result=new Bundle();result.putString("stream",output+"\nNative tests: "+passed+" passed, "+failed+" failed\n");result.putInt("passed",passed);result.putInt("failed",failed);finish(failed==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,result);
    }
}
